          "content": "```Объявление войны```\n\nОфициальное заявление Высшего Совета Митоцурской Империи(Дайдзёкан)\nО нелегитимности притязаний на статус центрального региона и несерьёзности «королевского» титула\n\nВвиду участившихся попыток искажения исторической правды и геополитических реалий, Высший Совет Митоцурской Империи выступает с официальным и бескомпромиссным заявлением:\n\nМитоцурская Империя категорически не признаёт Акрилию в качестве главного региона, равно как и не признаёт так называемого «короля» Лемона в качестве легитимного монарха.\n\nОсновные положения:\nО «главном регионе» (Акрилия):\nСтатус центра или ключевого региона не может определяться самопровозглашёнными амбициями. Акрилия не обладает ни историческим, ни экономическим, ни политическим весом для того, чтобы претендовать на доминирующее положение. Все попытки выдать её за главный регион Империя считает ничем иным, как дешёвой пропагандой и искажением действительности.\n\nО «короле» Лемоне:\nПретензии индивида по имени Лемон на королевский титул и верховную власть лишены какого-либо правового и династического основания. Митоцурская Империя считает его статус полностью нелегитимным, а его решения — не имеющими никакой юридической или политической силы.\n\nПозиция Империи:\n«Любые указы, договоры и претензии, исходящие от Акрилии и самопровозглашённого \"короля\" Лемона, объявляются ничтожными. Митоцурская Империя сохраняет за собой право действовать исключительно в интересах собственного суверенитета и порядка.»\n\nМитоцурская Империя призывает все сопредельные территории и фракции трезво оценивать реальное положение дел и не поддаваться на иллюзии, создаваемые акрилийской администрацией.\n\nПечать Высшего Совета Митоцурской Империи (Дайдзёкан)\n\nДокумент вступает в силу с момента обнародования.\n\n\n`Вторая мито-акрильская война`\n\n```Битва в воскресенье 19:00 по МСК```",
